(()=>{'use strict';
const details=[...document.querySelectorAll('.hw-content details')];const status=document.querySelector('.hw-status');
document.querySelectorAll('[data-expand]').forEach(button=>button.addEventListener('click',()=>{const open=button.dataset.expand==='all';details.forEach(item=>item.open=open);if(status)status.textContent=open?'已展开全部详解与多解。':'已收起详解，保留题目与短答。';}));
const dialog=document.createElement('dialog');dialog.className='hw-ask-dialog';dialog.setAttribute('aria-labelledby','hw-ask-title');
dialog.innerHTML='<h2 id="hw-ask-title">围绕这道题继续问 dot</h2><p>可在最后补充具体卡住的一步。仅复制到剪贴板，不会自动发送消息，也不包含阅读记录。</p><label for="hw-ask-text">提问内容</label><textarea id="hw-ask-text" rows="11"></textarea><div class="hw-tools"><button type="button" data-ask-copy>复制提问</button><button type="button" data-ask-close>关闭</button></div><p class="hw-ask-status" aria-live="polite"></p>';
document.body.append(dialog);const field=dialog.querySelector('textarea'),copy=dialog.querySelector('[data-ask-copy]'),close=dialog.querySelector('[data-ask-close]'),askStatus=dialog.querySelector('.hw-ask-status');let lastButton=null;
function plain(node){if(!node)return '';const clone=node.cloneNode(true);clone.querySelectorAll('.hw-math').forEach(x=>x.replaceWith(document.createTextNode('\\('+x.dataset.tex+'\\)')));return clone.textContent.trim().replace(/\s+/g,' ');}
document.querySelectorAll('.hw-content section.question,.hw-content article.problem').forEach(question=>{const heading=question.querySelector('h2');if(!heading)return;const button=document.createElement('button');button.type='button';button.className='hw-ask-open';button.textContent='向 dot 继续提问';button.setAttribute('aria-label','围绕'+heading.textContent.trim()+'向 dot 提问');heading.after(button);button.addEventListener('click',()=>{lastButton=button;const original=question.querySelector('.question-text,.problem-statement');const refs=[...question.querySelectorAll('.source a,.ppt-links a,.source-links a')].map(a=>a.textContent.trim()+'：'+a.href);const originals=[...question.querySelectorAll('img[src*="/original-"],img[src*="/dependency-"]')].map(img=>img.alt+'：'+new URL(img.getAttribute('src'),location.href).href);const current=new URL(location.href);current.hash=question.id;field.value='我正在做：'+heading.textContent.trim()+'\n\n题目：'+plain(original)+(question.querySelector('.course-convention')?'\n\n本课编码约定：'+plain(question.querySelector('.course-convention')):'')+'\n\n本题网页：'+current.href+(originals.length?'\n\n原题局部图（含依赖题，非重绘）：\n'+originals.join('\n'):'')+'\n\n相关原 PPT：\n'+[...new Set(refs)].join('\n')+'\n\n我卡住的具体一步：\n（请在这里补充；请以本题为根，先解释所需原 PPT 知识点，再带我完成这一步。）';askStatus.textContent='';dialog.showModal();field.focus();});});
close.addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>lastButton?.focus());
copy.addEventListener('click',async()=>{copy.disabled=true;try{await navigator.clipboard.writeText(field.value);askStatus.textContent='已复制。请粘贴到与 dot 的对话中发送。';}catch{field.focus();field.select();askStatus.textContent='浏览器未允许自动复制；文本已选中，可手动复制。';}finally{copy.disabled=false;}});
})();
